#!/usr/bin/env bash
# scripts/check_archive_fixture_coverage.sh
# Verifies that every hostile and benign archive fixture generated by
# scripts/make_hostile_archives.sh has at least one named assertion in
# PastaTests/main.swift (Section 39) or scripts/run_section8_tests.sh (Section 7.3).

set -euo pipefail

cd "$(dirname "$0")/.."

FIXTURES_DIR=$(mktemp -d /tmp/pasta_fixture_check_XXXXXX)
trap 'rm -rf "$FIXTURES_DIR"' EXIT

echo "Generating archive fixtures in $FIXTURES_DIR..."
./scripts/make_hostile_archives.sh "$FIXTURES_DIR" >/dev/null 2>&1

MISSING=0
TOTAL=0

echo "Checking test assertion coverage across Section 39 and Section 7.3..."
for fixture_path in "$FIXTURES_DIR"/*; do
    [ -e "$fixture_path" ] || continue
    fixture=$(basename "$fixture_path")
    TOTAL=$((TOTAL + 1))
    
    # Check if fixture name appears in an assertion string in PastaTests/main.swift or run_section8_tests.sh
    MATCH=$(grep -n -E "(assertTest|pass).*\($fixture\)" PastaTests/main.swift scripts/run_section8_tests.sh 2>/dev/null || \
            grep -n -E "(assertTest|pass).*$fixture" PastaTests/main.swift scripts/run_section8_tests.sh 2>/dev/null || true)
    
    if [ -n "$MATCH" ]; then
        echo "  ✓ Fixture '$fixture' asserted:"
        echo "    $MATCH" | head -n 1 | sed 's/^/    /'
    else
        echo "  ✗ ERROR: Fixture '$fixture' has NO named assertion in PastaTests/main.swift or scripts/run_section8_tests.sh!"
        MISSING=$((MISSING + 1))
    fi
done

echo "--------------------------------------------------"
echo "Archive Fixture Coverage: $((TOTAL - MISSING))/$TOTAL fixtures covered."

if [ "$MISSING" -gt 0 ]; then
    echo "ERROR: $MISSING fixtures lack test assertions. Gate failed."
    exit 1
fi

echo "✓ Gate passed: Every generated fixture has at least one named assertion."
exit 0
